merge="import json,csv\\nfrom benchmark_core.data import sha256\\nlatest={}\\nfor p in (ROOT/'03_model_raw_outputs').glob('*/*/fair_reference/*/run_manifest.json'):\\n m=json.loads(p.read_text()); key=(m['model_id'],m['dataset_id'])\\n if m.get('profile_id')=='fair_reference_v1' and m.get('timing_comparability') and m.get('protocol')==PROTOCOL and m['counts']['input'] in (921,100):latest[key]=m\\nif not latest:raise RuntimeError('沒有可合併的完整公平結果')\\nout=ROOT/'04_merged_results'/('merged_'+__import__('datetime').datetime.utcnow().strftime('%Y%m%dT%H%M%SZ'));out.mkdir(parents=True)\\nrows=[{'run_id':m['run_id'],'model_id':m['model_id'],'dataset_id':m['dataset_id'],**m['timing'],'handoff_hash':m['data_handoff_hash'],'timing_comparability':True} for m in latest.values()]\\nwith (out/'benchmark_table.csv').open('w',newline='',encoding='utf-8-sig') as f:w=csv.DictWriter(f,fieldnames=rows[0]);w.writeheader();w.writerows(rows)\\n(out/'merge_manifest.json').write_text(json.dumps({'profile_id':'fair_reference_v1','timing_comparability':True,'runs':[r['run_id'] for r in rows],'table_sha256':sha256(out/'benchmark_table.csv')},ensure_ascii=False,indent=2),encoding='utf-8');(ROOT/'04_merged_results/latest.json').write_text(json.dumps({'path':str(out.relative_to(ROOT))}),encoding='utf-8');print('✅',out)\\n"
write('90_Merge_FairReference_v4.ipynb','90｜合併可比較的 fair_reference run',[boot,merge])
analysis="import json,pandas as pd,ast\\nlatest=json.loads((ROOT/'04_merged_results/latest.json').read_text());df=pd.read_csv(ROOT/latest['path']/'benchmark_table.csv');adult=df[df.dataset_id=='coco_singleperson_val2017'].set_index('model_id');infant=df[df.dataset_id=='syrip_test100'].set_index('model_id');rows=[]\\nfor m in sorted(set(adult.index)&set(infant.index)):\\n a,i=adult.loc[m],infant.loc[m];rows.append({'model_id':m,'adult_end_to_end_oks':a.oks_e2e,'infant_end_to_end_oks':i.oks_e2e,'cross_age_oks_drop':a.oks_e2e-i.oks_e2e,'adult_coverage':a.coverage,'infant_coverage':i.coverage,'fair_latency_ms_median':(ast.literal_eval(a.latency_ms)['median']+ast.literal_eval(i.latency_ms)['median'])/2})\\nout=ROOT/'05_analysis_results'/('analysis_'+__import__('datetime').datetime.utcnow().strftime('%Y%m%dT%H%M%SZ'));out.mkdir(parents=True);pd.DataFrame(rows).to_csv(out/'cross_domain_summary.csv',index=False,encoding='utf-8-sig');(out/'analysis_manifest.json').write_text(json.dumps({'profile_id':'fair_reference_v1','main_score':'未偵測與錯誤在端到端 OKS/PCK 為 0；條件式 OKS/PCK 與 coverage 分開報告','ranking':'僅 fair_reference 延遲可以跨模型比較'},ensure_ascii=False,indent=2),encoding='utf-8');print('✅',out)\\n"
write('91_Analyse_TwoDomain_FairReference_v4.ipynb','91｜兩域公平基準分析',[boot,analysis])
